package org.freecad.mobilelab;
import org.json.*;
public final class PartDesignRoundPrimitiveAdapterHostTest {
    static int checks;
    static void check(boolean b,String why){if(!b)throw new AssertionError(why);checks++;}
    static JSONObject call(JSONObject q)throws Exception{JSONObject r=new JSONObject(CoreNative.request(q.toString()));check(r.getBoolean("ok"),r.optString("error"));return r.getJSONObject("state");}
    static JSONObject cmd(String s)throws Exception{return call(CoreCommandLine.parse(s));}
    static void bad(String s)throws Exception{JSONObject r=new JSONObject(CoreNative.request(CoreCommandLine.parse(s).toString()));check(!r.getBoolean("ok"),"Must reject "+s);}
    static void python(String code)throws Exception{JSONObject r=call(new JSONObject().put("op","python").put("code",code)).getJSONObject("python").getJSONObject("console");check(r.getString("error").isEmpty(),r.getString("error"));}
    static void volume(String n,double expected)throws Exception{JSONObject r=cmd("ShapeInfo "+n).getJSONObject("shape_inspection");check(r.getBoolean("valid")&&r.getInt("solids")==1,"Closed original solid");check(Math.abs(r.getDouble("volume")-expected)<1e-5,"Analytic volume "+n+": "+r);}
    public static void main(String[] a)throws Exception{
        System.load(a[3]);SignalProbe.capture();System.load(a[0]);CoreNative.initialize(a[1],a[2],a[1]);check(SignalProbe.preserved(),"JVM signals retained");cmd("NewDoc RoundPrimitives");cmd("Body Body");
        for(String s:new String[]{"BodySubCone Body EmptyCone 1 0 3","BodySubSphere Body EmptySphere 1","BodyAddSphere Body ZeroSphere 0","BodyAddSphere Body TinySphere 0.00000001","BodyAddSphere Body NegativeSphere -1","BodyAddCone Body ZeroCone 0 0 3","BodyAddCone Body NegativeCone -1 0 3","BodyAddCone Body ZeroHeight 1 0 0","BodyAddCone Body Oversized 1000001 0 1"})bad(s);
        cmd("BodyAddBox Body Stock 10 10 10");cmd("BodyAddSphere Body Dome 2 5 5 10 0 0 0");volume("Body",1000+16*Math.PI/3);
        cmd("BodyAddCone Body Cone 1 0 3 2 2 10 0 0 0");volume("Body",1000+19*Math.PI/3);
        cmd("BodySubSphere Body SphereCut 1 5 5 5 0 0 0");volume("Body",1000+5*Math.PI);
        cmd("BodySubCone Body ConeCut 1 0 3 2 2 0 0 0 0");volume("Body",1000+4*Math.PI);
        python("d=App.ActiveDocument\nassert [o.TypeId for o in (d.Dome,d.Cone,d.SphereCut,d.ConeCut)]==['PartDesign::AdditiveSphere','PartDesign::AdditiveCone','PartDesign::SubtractiveSphere','PartDesign::SubtractiveCone']\nassert d.Dome.BaseFeature==d.Stock and d.Cone.BaseFeature==d.Dome and d.SphereCut.BaseFeature==d.Cone and d.ConeCut.BaseFeature==d.SphereCut and d.Body.Tip==d.ConeCut\nassert (d.Dome.Angle1.Value,d.Dome.Angle2.Value,d.Dome.Angle3.Value)==(-90,90,360) and d.Cone.Angle.Value==360");
        for(String s:new String[]{"BodyAddSphere Body InsideSphere 1 7 7 2 0 0 0","BodyAddCone Body InsideCone 1 0 2 7 7 2 0 0 0","BodyAddSphere Body PointSphere 1 5 5 13 0 0 0","BodyAddCone Body PointCone 0 1 2 8 8 10 0 0 0","BodyAddSphere Body DetachedSphere 1 100 100 100 0 0 0","BodyAddCone Body DetachedCone 1 0 3 100 100 100 0 0 0","BodySubSphere Body OutsideSphere 1 100 100 100 0 0 0","BodySubCone Body OutsideCone 1 0 3 100 100 100 0 0 0","BodySubSphere Body WipeSphere 100 5 5 5 0 0 0","BodySubCone Body WipeCone 100 100 100 5 5 -1 0 0 0","BodyPrimitivePose Body Dome 1000000 0 0 0 0 0","BodyPrimitivePose Body Cone 999999 0 0 45 0 0","Set Dome.Angle1 0 deg","Set Dome.Angle2 45 deg","Set Dome.Angle3 180 deg","Set Cone.Angle 180 deg","Set SphereCut.Radius 0 mm","Set Cone.Radius1 0 mm","Set Cone.Radius2 -1 mm","Set Cone.Height 0 mm","Set Dome.Radius 1000001 mm","Set Cone.MapMode 1","Set SphereCut.Suppressed true","Set ConeCut.FuzzyTolerance 0","Expression Dome.Radius 3","PartPlacement Cone 2 2 10 0 0 0"})bad(s);
        volume("Body",1000+4*Math.PI);
        cmd("Set Stock.Height 11 mm");volume("Body",1100-10*Math.PI/27);
        cmd("Set Cone.Height 0.6 cm");volume("Body",1100+53*Math.PI/108);
        cmd("Set Dome.Radius 0.3 cm");check(cmd("ShapeInfo Body").getJSONObject("shape_inspection").getDouble("volume")>1100+53*Math.PI/108,"Sphere radius updates native material");cmd("Undo");volume("Body",1100+53*Math.PI/108);cmd("Redo");cmd("Undo");
        cmd("Set Cone.Radius2 1 mm");volume("Body",1100+13*Math.PI/3);cmd("Undo");
        cmd("BodyPrimitivePose Body SphereCut 6 5 5 30 20 10");volume("Body",1100+53*Math.PI/108);cmd("Undo");
        cmd("PartPlacement Body 1 2 3 30 20 10");volume("Body",1100+53*Math.PI/108);cmd("Undo");bad("PartPlacement Body 999999 0 0 0 0 0");
        cmd("BodyTip Body Stock");bad("BodyAddSphere Body Branched 1 5 5 11 0 0 0");cmd("BodyTip Body ConeCut");
        cmd("Begin RoundAtomic");cmd("Set Stock.Height 11.5 mm");bad("BodyPrimitivePose Body Dome 5 5 100 0 0 0");volume("Body",1100+53*Math.PI/108);python("assert abs(App.ActiveDocument.Stock.Height.Value-11)<1e-8");
        cmd("Body OtherBody");cmd("BodyAddSphere OtherBody Ball 2");volume("OtherBody",32*Math.PI/3);bad("BodyPrimitivePose Body Ball 0 0 0 0 0 0");
        cmd("Body ApexBody");cmd("BodyAddCone ApexBody Apex 0 2 3");volume("ApexBody",4*Math.PI);cmd("Set Apex.Radius1 2 mm");volume("ApexBody",12*Math.PI);cmd("Undo");
        cmd("Body EqualBody");cmd("BodyAddCone EqualBody Equal 1 1 3");volume("EqualBody",3*Math.PI);python("assert App.ActiveDocument.Equal.TypeId=='PartDesign::AdditiveCone'");
        cmd("RemoveBodyFeature Body ConeCut");volume("Body",1100+161*Math.PI/108);cmd("Undo");volume("Body",1100+53*Math.PI/108);
        cmd("Save RoundPrimitives.FCStd");Process cold=new ProcessBuilder(System.getProperty("java.home")+"/bin/java","-cp",System.getProperty("java.class.path"),"org.freecad.mobilelab.PartDesignRoundPrimitiveColdRestoreHostTest",a[0],a[1],a[2]).inheritIO().start();check(cold.waitFor()==0,"Original round primitive cold restoration");
        python("import zipfile,xml.etree.ElementTree as ET,mobile_core\nroot=mobile_core._root\nwith zipfile.ZipFile(root/'RoundPrimitives.FCStd') as z:saved={n:z.read(n) for n in z.namelist()}\ndef round_fixture(filename,obj,prop,tag,key,value):\n    tree=ET.fromstring(saved['Document.xml'])\n    node=tree.find(\"./ObjectData/Object[@name='\"+obj+\"']/Properties/Property[@name='\"+prop+\"']/\"+tag)\n    assert node is not None\n    node.set(key,value)\n    xml=ET.tostring(tree)\n    with zipfile.ZipFile(root/('BadRound'+filename+'.FCStd'),'w') as z:\n        for n,b in saved.items():z.writestr(n,xml if n=='Document.xml' else b)");
        String[] changes={"'BothZero','Cone','Radius1','Float','value','0'","'Negative','Cone','Radius2','Float','value','-1'","'SphereZero','Dome','Radius','Float','value','0'","'SphereNan','SphereCut','Radius','Float','value','nan'","'Height','Cone','Height','Float','value','1000001'","'ConeAngle','Cone','Angle','Float','value','180'","'SphereAngle1','Dome','Angle1','Float','value','0'","'SphereAngle2','Dome','Angle2','Float','value','45'","'SphereAngle3','Dome','Angle3','Float','value','180'","'Mode','Cone','MapMode','Integer','value','2'","'Engine','Dome','AttacherType','String','value','Attacher::AttachEnginePlane'","'Offset','Cone','AttachmentOffset','PropertyPlacement','Px','1'","'Reverse','Dome','MapReversed','Bool','value','true'","'PathParameter','Dome','MapPathParameter','Float','value','0.5'","'Suppressed','SphereCut','Suppressed','Bool','value','true'","'Tolerance','ConeCut','FuzzyTolerance','Float','value','0'","'PoseNan','SphereCut','Placement','PropertyPlacement','Py','nan'","'Quaternion','ConeCut','Placement','PropertyPlacement','Q3','2'","'ConeBounds','Cone','Placement','PropertyPlacement','Px','1000000'","'SphereBounds','Dome','Placement','PropertyPlacement','Pz','-1000000'","'BodyBounds','Body','Placement','PropertyPlacement','Px','999999'","'History','ConeCut','BaseFeature','Link','value','Stock'","'Foreign','ConeCut','BaseFeature','Link','value','Ball'"};
        for(String mutation:changes)python("round_fixture("+mutation+")");
        for(String n:new String[]{"BothZero","Negative","SphereZero","SphereNan","Height","ConeAngle","SphereAngle1","SphereAngle2","SphereAngle3","Mode","Engine","Offset","Reverse","PathParameter","Suppressed","Tolerance","PoseNan","Quaternion","ConeBounds","SphereBounds","BodyBounds","History","Foreign"})bad("Open BadRound"+n+".FCStd");
        volume("Body",1100+53*Math.PI/108);cmd("ExportStep Body RoundPrimitives.step");cmd("ImportStep Copy RoundPrimitives.step");volume("Copy",1100+53*Math.PI/108);
        cmd("Close");cmd("Open RoundPrimitives.FCStd");volume("Body",1100+53*Math.PI/108);volume("ApexBody",4*Math.PI);volume("EqualBody",3*Math.PI);
        System.out.println("PASS original round primitive JNI checks: "+checks);
    }
}
